 template<class T>const T*task()const{if(complete())return nullptr;if constexpr(std::is_same_v<T,StateCentralActionsService>)return this;else if constexpr(std::is_same_v<T,Coordinator>)return active_==Component::Policy?&coordinator_:nullptr;else{switch(active_){case Component::Policy:return coordinator_.template task<T>();case Component::Events:if constexpr(std::is_same_v<T,StateEventsService>)return &*events_[slot_];else if constexpr(std::is_same_v<T,PanelInputTask>)return events_[slot_]->panelTask();else if constexpr(std::is_same_v<T,PanelAnalogTask>)return events_[slot_]->analogTask();else return nullptr;case Component::Screen:return taskOf<T>(*screens_[slot_]);case Component::Probe:if constexpr(std::is_same_v<T,StateMenuService>)return &*probes_[slot_];else return nullptr;case Component::Settings:if constexpr(std::is_same_v<T,PanelSettingsService>)return &*settings_;else return nullptr;case Component::Controls:if constexpr(std::is_same_v<T,PanelControlsService>)return &*controls_;else return nullptr;case Component::Dsp:return taskOf<T>(*dsp_);case Component::Midi:return taskOf<T>(*midi_);case Component::Field:return taskOf<T>(*fields_[slot_]);case Component::Action:return std::visit([&](const auto&t)->const T*{return taskOf<T>(t);},heavy_);case Component::Lower:return taskOf<T>(*lower_[slot_]);case Component::Reset:return taskOf<T>(*resets_[slot_]);case Component::Program:return taskOf<T>(*program_);case Component::Apply:return taskOf<T>(*apply_);case Component::Panel:if constexpr(std::is_same_v<T,StateReloadPanelService>)return &*panel_;else return nullptr;case Component::Save:return taskOf<T>(*save_);case Component::Repeat:if constexpr(std::is_same_v<T,ScheduledTimerTask>)return repeat_->clock?nullptr:&repeat_->timer;else if constexpr(std::is_same_v<T,ControllerClockReadTask>)return repeat_->clock?&*repeat_->clock:nullptr;else return nullptr;case Component::Display:if constexpr(std::is_same_v<T,StateDisplayService>)return &*display_;else return nullptr;case Component::External:return nullptr;}return nullptr;}}
