  case Component::Screen:{auto&t=*screens_[slot_];t.advanceBefore(cost,read,write,resolve,previous);finished(t);if(done){nonzero=t.summary().gate.accepted;presentation=t.kind()==StateScreenService::Kind::Gate?r.input.presentation:renderPresentation(t.summary());}}break;
