 static uint16_t renderPresentation(const StateScreenService::Summary&s){auto word=s.labelWord;const auto&v=s.value;if(!v.observed||!v.type)return word;const auto display=[&](const StateScreenService::DisplayResult&d){using P=StateDisplayService::Presentation;if(d.presentation==P::Table||d.presentation==P::Text||d.presentation==P::Disabled||d.presentation==P::Character)word=d.output;};word=uint16_t((word&0xff00)|145);display(v.currentDisplay);if(v.current==v.reference)display(v.matchDisplay);else{word=uint16_t((word&0xff00)|209);display(v.referenceDisplay);}return word;}
 template<class View>static uint16_t uiPresentation(const View&view){const auto*ui=view.lastRefresh();if(!ui)throw std::logic_error("Missing central UI outcome");if(ui->automaticIndex!=~0u){const auto child=view.completedView(ui->automaticIndex);const auto&w=child.summary().editWorkflow?child.summary().editWorkflow:child.summary().workflow;if(!w)throw std::logic_error("Missing central automatic input");return w->input.event;}if(ui->rendered){const auto*s=view.lastScreen();if(!s)throw std::logic_error("Missing central rendered view");return renderPresentation(*s);}return ui->character;}
 static uint16_t editPresentation(const StateFieldService&s){const auto*e=s.sceneEditRootSummary();if(!e)throw std::logic_error("Missing central name outcome");const auto v=s.projectionView().sceneEditView();if(e->uiObserved)return uiPresentation(v);if(e->sceneObserved){const auto scene=v.sceneView();if(const auto*o=scene.sceneRootSummary())if(o->uiObserved)return uiPresentation(scene);}return e->presentation;}
 static uint16_t fieldPresentation(const StateFieldService&s,Request q,uint16_t in){if(q==Request::UiRefresh)return uiPresentation(s.projectionView());if(q==Request::Notify){const auto*o=s.sceneRootSummary();if(!o)throw std::logic_error("Missing central notify outcome");return o->uiObserved?uiPresentation(s.projectionView().sceneView()):o->presentation;}if(q==Request::NameInsertDigit||q==Request::NameToggle||q==Request::NameInsertSpace||q==Request::NameClearSuffix||q==Request::SceneDecrement||q==Request::SceneIncrement)return editPresentation(s);return in;}
 static uint16_t resetPresentation(const StatePlaybackResetService&s,uint16_t in){if(s.kind()==StatePlaybackResetService::Kind::Panic)return in&0xff00;if(s.kind()==StatePlaybackResetService::Kind::ReleaseVoices&&s.voices()->releasedAny())return uint16_t(s.voices()->lastPatch());return in;}
 static uint16_t heavyPresentation(const StateEditActionService&s,uint16_t){if(s.ui())return uiPresentation(s.ui()->projectionView());if(s.summary().screenSet)return renderPresentation(*s.summary().setOutcome);return s.summary().presentation;}
 static uint16_t heavyPresentation(const StateProgramBrowserService&s,uint16_t){return s.summary().presentation;}
 static uint16_t heavyPresentation(const StateStoreMenuService&s,uint16_t){if(s.playback())return heavyPresentation(*s.playback(),s.summary().presentation);if(s.factory()&&s.factory()->notice())return uint16_t(s.factory()->notice()->tick());return s.summary().presentation;}
 static uint16_t heavyPresentation(const StatePlaybackModeService&s,uint16_t){auto word=s.ui()?uiPresentation(s.ui()->projectionView()):s.coordinator().presentation();for(unsigned n=0;n<24;++n)if(const auto*r=s.resetOutcome(n))word=resetPresentation(*r,word);return word;}
 static uint16_t heavyPresentation(const StatePartNavigationService&s,uint16_t){if(s.field())return s.summary().sceneEdit?editPresentation(*s.field()):uiPresentation(s.field()->projectionView());return s.summary().presentation;}
 static uint16_t heavyPresentation(const StateSceneToggleService&s,uint16_t in){if(s.facts().refresh)return uiPresentation(s.field()->projectionView());if(s.facts().notice)return uint16_t(s.save()->tick());if(s.facts().checkObserved&&!s.facts().available&&s.checked())return uint16_t(s.checked()->tick());return in;}
