 template<class R>struct CaptureResolver{R&base;uint32_t&recipe;StateFieldCoordinator::Handler field(uint8_t c,uint32_t raw){return base.field(c,raw);}bool schema(uint8_t c,uint32_t raw){return base.schema(c,raw);}bool packing(uint32_t raw){return base.packing(raw);}StatePackFieldsTask::Kind operator()(uint32_t raw){recipe=raw;return base(raw);}bool operator()(uint8_t c,uint32_t raw){return base(c,raw);}};
 static bool readEndpoint(uint32_t a){return StateStoreService::dataSpan(a,1)||(a>=0x1b0&&a<0x1bc)||(a>=0x1c0&&a<0x300)||(a>=0x800000&&a<0x900000)||(a>=0x400000&&a<0x400010)||(a>=0x600000&&a<0x600010)||a==0xffff50||a==0xffff51||a==0xffff53||a==0xffff61||a==0xffff62||a==0xfffeb1||(a>=0xffff80&&a<0xffffa0)||(a>=0xffffa4&&a<=0xffffa6)||a==0xfffff6||a==0xfffff7;}
