 // Existing native capsules have intentionally narrow task variants. A
 // syntactically callable getter is not evidence that get_if<T> is valid.
 template<class T,class...U>static constexpr bool oneOf(){return(std::is_same_v<T,U>||...);}
 template<class T>static constexpr bool fieldTaskType(){return oneOf<T,StateFieldCoordinator,StateApplyService,StateDisplayService,StateScreenService,StateUiRefreshService,StateStoreService,StateFieldPacketService,PanelSettingsLcdService,StateSceneCoordinator,StateSceneEditCoordinator,StateVoiceRefreshService>();}
