 template<class S,class T,class=void>struct HasTask:std::false_type{};template<class S,class T>struct HasTask<S,T,std::void_t<decltype(std::declval<const S&>().template task<T>())>>:std::true_type{};
 template<class T,class S>static const T*taskOf(const S&s){
  if constexpr(std::is_same_v<T,S>)return &s;
  else if constexpr(std::is_same_v<S,StateFieldService>){if constexpr(fieldTaskType<T>())return s.template task<T>();else return nullptr;}
  else if constexpr(std::is_same_v<S,StateScreenService>){if constexpr(screenTaskType<T>())return s.template task<T>();else return nullptr;}
  else if constexpr(std::is_same_v<S,StateSaveService>){if constexpr(saveTaskType<T>())return s.template task<T>();else return nullptr;}
  else if constexpr(std::is_same_v<S,StatePartNavigationService>){if constexpr(fieldTaskType<T>()||oneOf<T,StateScreenActionsTask,StateBankNavigationTask,StatePlaybackModeCoordinator,StateModeTask,StateStorageTask,StatePartSelectionTask>())return s.template task<T>();else return nullptr;}
  else if constexpr(std::is_same_v<S,StateEditActionService>){using C=StateEditActionService::Component;switch(s.component()){
   case C::Action:if constexpr(std::is_same_v<T,StateScreenActionsTask>)return &s.actionTask();else return nullptr;
   case C::ClearDigits:if constexpr(std::is_same_v<T,StateProgramBrowseTask>)return s.digitsTask();else return nullptr;
   case C::Gate:case C::ScreenSet:{const auto*p=s.template task<StateScreenService>();return p?taskOf<T>(*p):nullptr;}
   case C::CalibrationReset:{const auto*p=s.template task<PanelSettingsService>();if constexpr(std::is_same_v<T,PanelSettingsService>)return p;else return nullptr;}
   case C::Apply:return s.apply()?taskOf<T>(*s.apply()):nullptr;
   case C::UiRefresh:return s.ui()?taskOf<T>(*s.ui()):nullptr;
  }return nullptr;}
  else if constexpr(HasTask<S,T>::value)return s.template task<T>();else return nullptr;
 }
 template<class T,std::size_t N,class...Args>uint8_t place(std::array<std::optional<T>,N>&pool,Args&&...args){for(unsigned n=0;n<N;++n)if(!pool[n]){pool[n].emplace(std::forward<Args>(args)...);return uint8_t(n);}throw std::logic_error("Central UI native outcome pool capacity");}
